import AppKit

/// The leading icon a tab — in the strip and in the ⇧⌘J switcher — shows for
/// the kind of file behind it (SPEC Todo 15).
///
/// The name is all there is to go on: a tab's title is its file's last path
/// component, and the switcher is handed titles, not URLs. So the extension
/// decides, and a note with no file at all is asked for by its `nil` URL
/// rather than by a name it does not have.
///
/// Most kinds draw this app's own hand-drawn icon set (`FileKindArt`,
/// generated by `Icon/make-file-icons.py` from the sibling `favcon` repo).
/// A kind the set has no art for falls back to an SF Symbol, the way every
/// kind used to work; a couple of those symbols only arrived in the macOS 15
/// SF Symbols set, and one that is not there draws nothing at all rather
/// than falling back on its own — so each of those kinds names its
/// preferred symbol and the older spelling behind it, and the first one the
/// running system actually has is the one used.
enum FileKindIcon {

    /// A note that has never been saved: no name, so no kind. Always the
    /// plain SF Symbol `doc`, never the custom art — this is the one case
    /// that has to stay recognizable as "nothing yet" rather than a kind.
    static var untitledSymbolName: String { resolved(["doc"]) }

    /// The icon name for a note's file. `nil` — an untitled note — is a
    /// plain `doc`, which is the one case a name could never tell us about.
    /// A `"filetype-<stem>"` name is this app's own art, drawn by
    /// `image(named:pointSize:)`; anything else is an SF Symbol name.
    static func symbolName(for url: URL?) -> String {
        guard let url else { return untitledSymbolName }
        return symbolName(forTitle: url.lastPathComponent)
    }

    /// The icon name for a file name, which is what a tab title is.
    static func symbolName(forTitle title: String) -> String {
        let ext = (title as NSString).pathExtension.lowercased()
        if let stem = artStem(forExtension: ext) {
            return "filetype-\(stem)"
        }
        return resolved(candidates(forExtension: ext))
    }

    /// The image to actually draw for a name `symbolName(for:)` /
    /// `symbolName(forTitle:)` returned, at `pointSize`. A `"filetype-*"`
    /// name loads this app's own art as a template image, so it tints with
    /// `contentTintColor` exactly like an SF Symbol; anything else is asked
    /// of AppKit as an SF Symbol, same as every icon used to be drawn.
    static func image(named name: String, pointSize: CGFloat) -> NSImage? {
        if name.hasPrefix(artPrefix) {
            return artImage(named: name, pointSize: pointSize)
        }
        return NSImage(systemSymbolName: name, accessibilityDescription: nil)?
            .withSymbolConfiguration(NSImage.SymbolConfiguration(pointSize: pointSize, weight: .regular))
    }

    // MARK: - Custom art

    private static let artPrefix = "filetype-"

    /// Extension → the custom art set's file stem (its SVG's file name,
    /// with aliases folded onto the spelling that was actually drawn), for
    /// every kind the set has a drawing for. `nil` means the set has
    /// nothing for this extension, so an SF Symbol is used instead.
    private static func artStem(forExtension ext: String) -> String? {
        switch ext {
        case "css": return "css"
        case "csv", "tsv": return "csv"
        case "epub": return "epub"
        case "gif": return "gif"
        case "go": return "go"
        case "html", "htm", "xhtml": return "html"
        case "jpg", "jpeg": return "jpg"
        case "js", "jsx", "mjs": return "js"
        case "json": return "json"
        case "md", "markdown", "mdown", "mkd": return "md"
        case "pdf": return "pdf"
        case "png": return "png"
        case "py": return "py"
        case "rs": return "rs"
        case "sh", "zsh", "bash": return "sh"
        case "sql": return "sql"
        case "svg": return "svg"
        case "swift": return "swift"
        case "tex", "latex", "ltx": return "tex"
        case "toml": return "toml"
        case "ts", "tsx": return "ts"
        case "txt", "text", "": return "txt"
        case "xml": return "xml"
        case "yaml", "yml": return "yaml"
        case "zip": return "zip"
        default: return nil
        }
    }

    /// One image per `(name, pointSize)` asked for, built once. Rebuilding
    /// an `NSImage` from SVG text on every row draw would be wasteful.
    private static var artImageCache: [String: NSImage] = [:]

    /// An SF Symbol at point size P draws about 1.2 P of ink; the art's
    /// ink — the document outline and the label under it — spans about
    /// three-quarters of its square. So the square is drawn at 1.5 P for the
    /// two to stand the same height side by side: 17 for the strip's 11pt
    /// (its 16pt slot clips that to 16 through `scaleProportionallyDown`),
    /// 18 in the Bookmarks menu beside its 12pt symbols, and the picker's
    /// 16pt slot takes what it can. The SVG is a vector rep, so any of these
    /// is crisp, 2× on Retina included. Measured off an offscreen render
    /// of both next to each other, not guessed.
    private static let artScale: CGFloat = 1.5

    private static func artImage(named name: String, pointSize: CGFloat) -> NSImage? {
        let stem = String(name.dropFirst(artPrefix.count))
        let cacheKey = "\(name)@\(pointSize)"
        if let cached = artImageCache[cacheKey] { return cached }
        guard let svg = FileKindArt.svg[stem],
              let data = svg.data(using: .utf8),
              let image = NSImage(data: data)
        else { return nil }
        image.isTemplate = true
        let side = (pointSize * artScale).rounded()
        image.size = NSSize(width: side, height: side)
        artImageCache[cacheKey] = image
        return image
    }

    // MARK: - SF Symbol fallback

    /// The preferred symbol first, older spellings after it. Only reached
    /// for a kind `artStem(forExtension:)` has no drawing for.
    private static func candidates(forExtension ext: String) -> [String] {
        switch ext {
        case "heic", "heif", "webp", "tiff", "tif", "bmp":
            return ["photo"]
        case "sty", "bib":
            return ["function", "x.squareroot"]
        case "plist":
            return ["curlybraces"]
        case "tsv":
            return ["tablecells"]
        case "rtf", "rtfd":
            return ["doc.richtext"]
        case "log":
            return ["list.bullet.rectangle"]
        case "rb", "c", "h", "cpp", "cc", "hpp", "m", "mm", "java", "kt",
             "pl", "php", "lua", "scss":
            return ["chevron.left.forwardslash.chevron.right"]
        default:
            return ["text.page", "doc"]
        }
    }

    /// The first of `names` the running system can actually draw, `doc` if
    /// it can draw none of them. Asking AppKit for an image on every row
    /// would be wasteful, so each answer is kept.
    private static var resolvedNames: [String: String] = [:]

    private static func resolved(_ names: [String]) -> String {
        let key = names.joined(separator: "|")
        if let cached = resolvedNames[key] { return cached }
        let answer = names.first { NSImage(systemSymbolName: $0, accessibilityDescription: nil) != nil }
            ?? "doc"
        resolvedNames[key] = answer
        return answer
    }
}
